const quote = (text) => `'${String(text).replace(/'/g, "''")}'`;
const data = $input.first().json;
const name = data.workflow?.name || 'không rõ tên';
const error = data.execution?.error?.message || 'không có thông báo lỗi';
const node = data.execution?.lastNodeExecuted || 'không rõ nút';
const title = `Quy trình n8n lỗi: ${name}`.slice(0, 200);
const detail = `Nút lỗi: ${node}. ${error}`.slice(0, 500);
return [{ json: { title_sql: quote(title), detail_sql: quote(detail) } }];
